css:
.scg-reading-bar{--scg-rb-ink:#eef1fa;--scg-rb-dim:#8b93a8;--scg-rb-a:#ffb454;--scg-rb-b:#ff6a88;box-sizing:border-box;width:100%;max-width:352px;border-radius:16px;overflow:hidden;background:linear-gradient(180deg,#12151d,#0b0d13);border:1px solid rgba(255,255,255,.08);color:var(--scg-rb-ink);font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;box-shadow:0 14px 34px -20px #000;}
.scg-reading-bar *{box-sizing:border-box;}
.scg-reading-bar-view{height:228px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.16) transparent;}
.scg-reading-bar-view::-webkit-scrollbar{width:6px;}
.scg-reading-bar-view::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:99px;}
.scg-reading-bar-sticky{position:sticky;top:0;z-index:2;padding:11px 14px 10px;background:linear-gradient(180deg,#0b0d13 0,#0b0d13 74%,rgba(11,13,19,0));-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);}
.scg-reading-bar-row{display:flex;align-items:baseline;gap:8px;margin:0 0 8px;}
.scg-reading-bar-kicker{font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--scg-rb-dim);}
.scg-reading-bar-left{margin-left:auto;font-size:10.5px;font-variant-numeric:tabular-nums;color:var(--scg-rb-dim);transition:color .3s ease;}
.scg-reading-bar-done .scg-reading-bar-left{color:var(--scg-rb-a);}
.scg-reading-bar-track{position:relative;height:4px;border-radius:99px;background:rgba(255,255,255,.09);overflow:hidden;}
.scg-reading-bar-fill{position:absolute;inset:0;border-radius:99px;transform:scaleX(0);transform-origin:0 50%;background:linear-gradient(90deg,var(--scg-rb-a),var(--scg-rb-b));box-shadow:0 0 10px -2px rgba(255,106,136,.7);}
.scg-reading-bar-fill::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);transform:translate3d(-100%,0,0);animation:scg-reading-bar-shine 3.2s ease-in-out infinite;}
.scg-reading-bar-doc{padding:2px 14px 18px;}
.scg-reading-bar-doc h3{margin:0 0 9px;font-size:15.5px;line-height:1.22;letter-spacing:-.015em;}
.scg-reading-bar-doc p{margin:0 0 10px;font-size:11.5px;line-height:1.68;color:#a7afc4;}
.scg-reading-bar-sig{margin:14px 0 0 !important;padding-top:9px;border-top:1px solid rgba(255,255,255,.07);font-size:10px;letter-spacing:.04em;color:#6d7590;}
@supports (animation-timeline: scroll()){
.scg-reading-bar-view{scroll-timeline-name:--scg-reading-bar-tl;scroll-timeline-axis:block;}
.scg-reading-bar-fill{animation:scg-reading-bar-grow linear both;animation-timeline:--scg-reading-bar-tl;}
}
@keyframes scg-reading-bar-grow{from{transform:scaleX(0);}to{transform:scaleX(1);}}
@keyframes scg-reading-bar-shine{0%{transform:translate3d(-110%,0,0);}55%,100%{transform:translate3d(220%,0,0);}}
@media (prefers-reduced-motion: reduce){
.scg-reading-bar-fill::after{animation:none;opacity:0;}
.scg-reading-bar-left{transition:none;}
.scg-reading-bar-view{scroll-behavior:auto;}
}

