var view = root.querySelector('.scg-reading-bar-view');
var fill = root.querySelector('.scg-reading-bar-fill');
var track = root.querySelector('.scg-reading-bar-track');
var left = root.querySelector('.scg-reading-bar-left');
var total = parseFloat(left.getAttribute('data-total')) || 7;
var native = !!(window.CSS && CSS.supports && CSS.supports('animation-timeline', 'scroll()') && CSS.supports('scroll-timeline-name', '--t'));
function update(){
  var max = view.scrollHeight - view.clientHeight;
  var p = max > 0 ? Math.min(1, Math.max(0, view.scrollTop / max)) : 0;
  if (!native) fill.style.transform = 'scaleX(' + p.toFixed(4) + ')';
  track.setAttribute('aria-valuenow', String(Math.round(p * 100)));
  var mins = Math.ceil(total * (1 - p));
  left.textContent = p > 0.995 ? 'Finished' : (mins <= 1 ? 'Under a minute left' : mins + ' min left');
  root.classList.toggle('scg-reading-bar-done', p > 0.995);
}
view.addEventListener('scroll', update, { passive: true });
update();

