var view = root.querySelector('.scg-ring-gauge-view');
var arc = root.querySelector('.scg-ring-gauge-arc');
var out = root.querySelector('.scg-ring-gauge-pct');
var side = root.querySelector('.scg-ring-gauge-side');
var LEN = 251.33;
function update(){
  var max = view.scrollHeight - view.clientHeight;
  var p = max > 0 ? Math.min(1, Math.max(0, view.scrollTop / max)) : 1;
  arc.style.strokeDashoffset = (LEN * (1 - p)).toFixed(2);
  var n = Math.round(p * 100);
  if (out.textContent !== String(n)) out.textContent = String(n);
  side.setAttribute('aria-valuenow', String(n));
}
view.addEventListener('scroll', update, { passive: true });
update();

