  view.addEventListener('scroll', function(){
    var line = view.scrollTop + view.clientHeight * 0.5, best = 0;
    for (var i = 0; i < secs.length; i++) if (secs[i].offsetTop <= line) best = i;
    setActive(best);
  }, { passive: true });
}

