var view = root.querySelector('.scg-chapter-rail-view');
var secs = [].slice.call(root.querySelectorAll('.scg-chapter-rail-ch'));
var marks = [].slice.call(root.querySelectorAll('.scg-chapter-rail-mark'));
var fills = [].slice.call(root.querySelectorAll('.scg-chapter-rail-fill'));
var now = root.querySelector('.scg-chapter-rail-now');
var title = root.querySelector('.scg-chapter-rail-title');
var names = marks.map(function(m){ return m.querySelector('.scg-chapter-rail-name').textContent; });
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
