    var h = secs[i].offsetHeight || 1;
    var f = atEnd ? 1 : Math.min(1, Math.max(0, (line - secs[i].offsetTop) / h));
    fills[i].style.height = (f * 100).toFixed(1) + '%';
    if (f > 0) live = i;
    marks[i].setAttribute('data-state', f >= 1 ? 'done' : (f > 0 ? 'live' : 'idle'));
  }
  if (atEnd) live = secs.length - 1;
  marks[live].setAttribute('data-state', marks[live].getAttribute('data-state') === 'done' && !atEnd ? 'done' : 'live');
  now.textContent = 'Chapter ' + (live + 1) + ' of ' + secs.length;
  title.textContent = names[live];
