marks.forEach(function(m, i){
  m.addEventListener('click', function(){
    view.scrollTo({ top: Math.max(0, secs[i].offsetTop - 6), behavior: reduce ? 'auto' : 'smooth' });
  });
});
view.addEventListener('scroll', update, { passive: true });
update();

