var view = root.querySelector('.scg-doc-minimap-view');
var map = root.querySelector('.scg-doc-minimap-map');
var lens = root.querySelector('.scg-doc-minimap-lens');
var pct = root.querySelector('.scg-doc-minimap-pct');
var scale = 1, tries = 0, dragging = false;
function sync(){
  var max = view.scrollHeight - view.clientHeight;
  lens.style.height = Math.max(8, view.clientHeight * scale) + 'px';
  lens.style.transform = 'translateY(' + (view.scrollTop * scale).toFixed(1) + 'px)';
  pct.textContent = Math.round(max > 0 ? (view.scrollTop / max) * 100 : 100) + '%';
