    m.className = 'scg-doc-minimap-blk scg-doc-minimap-' + (b.getAttribute('data-kind') || 'p');
    m.style.top = (b.offsetTop * scale).toFixed(1) + 'px';
    m.style.height = Math.max(2, b.offsetHeight * scale).toFixed(1) + 'px';
    frag.appendChild(m);
  }
  map.insertBefore(frag, lens);
  sync();
