function jump(clientY){
  var r = map.getBoundingClientRect();
  var lh = view.clientHeight * scale;
  var p = (clientY - r.top - lh / 2) / Math.max(1, r.height - lh);
  view.scrollTop = Math.min(1, Math.max(0, p)) * (view.scrollHeight - view.clientHeight);
