map.addEventListener('pointerup', stop);
map.addEventListener('pointercancel', stop);
function init(){
  if (!root.isConnected) return;
  if ((!view.clientHeight || !view.scrollHeight) && tries++ < 60) { requestAnimationFrame(init); return; }
