var view = root.querySelector('.scg-percent-readout-view');
var val = root.querySelector('.scg-percent-readout-val');
var big = root.querySelector('.scg-percent-readout-big');
var words = root.querySelector('.scg-percent-readout-words');
var state = root.querySelector('.scg-percent-readout-state');
var ticks = [].slice.call(root.querySelectorAll('.scg-percent-readout-tick'));
var total = parseInt(words.getAttribute('data-total'), 10) || 1480;
function comma(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
var last = -1;
function update(){
  var max = view.scrollHeight - view.clientHeight;
  var p = max > 0 ? Math.min(1, Math.max(0, view.scrollTop / max)) : 1;
  var n = Math.round(p * 100);
  if (n !== last) {
    last = n;
    val.textContent = String(n);
    big.setAttribute('aria-valuenow', String(n));
    words.textContent = comma(Math.round(p * total)) + ' of ' + comma(total) + ' words';
    for (var i = 0; i < ticks.length; i++) {
      var lit = ticks.length > 1 ? (i / (ticks.length - 1)) <= p + 0.001 : p > 0;
      ticks[i].classList.toggle('scg-percent-readout-lit', lit && p > 0);
    }
    state.textContent = p === 0 ? 'Ready to read' : (p > 0.995 ? 'Complete' : (p < 0.5 ? 'Reading' : 'Home stretch'));
  }
}
view.addEventListener('scroll', update, { passive: true });
update();

