var view = root.querySelector('.scg-segment-track-view');
var secs = [].slice.call(root.querySelectorAll('.scg-segment-track-sec'));
var segs = [].slice.call(root.querySelectorAll('.scg-segment-track-seg'));
var fills = [].slice.call(root.querySelectorAll('.scg-segment-track-fill'));
var step = root.querySelector('.scg-segment-track-step');
var label = root.querySelector('.scg-segment-track-label');
var titles = secs.map(function(s){ return s.querySelector('h4').textContent; });
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
function update(){
  var atEnd = view.scrollTop + view.clientHeight >= view.scrollHeight - 2;
  var line = view.scrollTop + view.clientHeight * 0.38;
  var live = 0;
  for (var i = 0; i < secs.length; i++) {
    var f = atEnd ? 1 : Math.min(1, Math.max(0, (line - secs[i].offsetTop) / (secs[i].offsetHeight || 1)));
    fills[i].style.width = (f * 100).toFixed(1) + '%';
    if (f > 0) live = i;
    segs[i].setAttribute('data-state', f >= 1 ? 'done' : (f > 0 ? 'live' : 'idle'));
  }
  if (atEnd) { live = secs.length - 1; segs[live].setAttribute('data-state', 'done'); }
  else if (segs[live].getAttribute('data-state') === 'done' && live < secs.length - 1) live = live + 1;
  step.textContent = 'Step ' + (live + 1) + ' of ' + secs.length;
  label.textContent = titles[live];
  for (var k = 0; k < segs.length; k++) segs[k].setAttribute('aria-current', k === live ? 'step' : 'false');
}
segs.forEach(function(b, i){
  b.addEventListener('click', function(){
    view.scrollTo({ top: Math.max(0, secs[i].offsetTop - 4), behavior: reduce ? 'auto' : 'smooth' });
  });
});
view.addEventListener('scroll', update, { passive: true });
update();

