var strip = root.querySelector('.scg-filmstrip-scrub-strip');
var fill = root.querySelector('.scg-filmstrip-scrub-fill');
var track = root.querySelector('.scg-filmstrip-scrub-track');
var tc = root.querySelector('.scg-filmstrip-scrub-tc');
var now = root.querySelector('.scg-filmstrip-scrub-now');
var btns = root.querySelectorAll('.scg-filmstrip-scrub-btn');
var shots = [].slice.call(root.querySelectorAll('.scg-filmstrip-scrub-shot'));
var total = 0, i;
for (i = 0; i < shots.length; i++) total += parseInt(shots[i].getAttribute('data-dur'), 10) || 0;
function fmt(s){
  s = Math.max(0, Math.round(s));
  var m = Math.floor(s / 60), r = s % 60;
  return m + ':' + (r < 10 ? '0' + r : r);
}
function step(){
  return shots.length > 1 ? shots[1].offsetLeft - shots[0].offsetLeft : 128;
}
function marks(){
  var max = strip.scrollWidth - strip.clientWidth;
  if (max <= 0) return;
  for (var k = 1; k < shots.length; k++) {
    var at = (shots[k].offsetLeft - shots[0].offsetLeft) / max * 100;
    if (at > 99) break;
    var m = document.createElement('span');
    m.className = 'scg-filmstrip-scrub-mark';
    m.style.left = at.toFixed(2) + '%';
    track.appendChild(m);
  }
}
function update(){
  var max = strip.scrollWidth - strip.clientWidth;
  var p = max > 0 ? Math.min(1, Math.max(0, strip.scrollLeft / max)) : 0;
  fill.style.width = (p * 100).toFixed(2) + '%';
  track.setAttribute('aria-valuenow', String(Math.round(p * 100)));
  tc.textContent = fmt(p * total) + ' / ' + fmt(total);
  var st = step(), idx = 0;
  if (st > 0) idx = Math.min(shots.length - 1, Math.max(0, Math.round(strip.scrollLeft / st)));
  if (p > 0.995) idx = shots.length - 1;
  for (var k = 0; k < shots.length; k++) shots[k].classList.toggle('scg-filmstrip-scrub-on', k === idx);
  var cap = shots[idx].querySelector('.scg-filmstrip-scrub-cap');
  now.textContent = 'Shot ' + (idx < 9 ? '0' : '') + (idx + 1) + ' · ' + cap.textContent;
  btns[0].disabled = p <= 0.001;
  btns[1].disabled = p >= 0.999;
