var panel = root.querySelector('.scg-step-ladder-panel');
var rungs = [].slice.call(root.querySelectorAll('.scg-step-ladder-rung'));
var secs = [].slice.call(root.querySelectorAll('.scg-step-ladder-sec'));
var active = -1;
function paint(i){
  if (i === active) return;
  active = i;
  for (var k = 0; k < rungs.length; k++) {
    rungs[k].classList.toggle('scg-step-ladder-live', k === i);
    rungs[k].classList.toggle('scg-step-ladder-done', k < i);
    rungs[k].setAttribute('aria-current', k === i ? 'step' : 'false');
  }
}
function atEnd(){
  return panel.scrollTop + panel.clientHeight >= panel.scrollHeight - 2;
}
function nearest(){
  var line = panel.scrollTop + panel.clientHeight * 0.5, best = 0;
  for (var k = 0; k < secs.length; k++) if (secs[k].offsetTop <= line) best = k;
  paint(atEnd() ? secs.length - 1 : best);
}
for (var i = 0; i < rungs.length; i++) {
  rungs[i].addEventListener('click', function(e){
    var n = parseInt(e.currentTarget.getAttribute('data-i'), 10);
    panel.scrollTop = secs[n].offsetTop - 4;
  });
}
if (window.IntersectionObserver) {
  var io = new IntersectionObserver(function(entries){
    if (atEnd()) { paint(secs.length - 1); return; }
    for (var j = 0; j < entries.length; j++) if (entries[j].isIntersecting) {
      paint(secs.indexOf(entries[j].target));
    }
  }, { root: panel, rootMargin: '-50% 0px -50% 0px', threshold: 0 });
  for (var s = 0; s < secs.length; s++) io.observe(secs[s]);
}
panel.addEventListener('scroll', nearest, { passive: true });
nearest();

