var doc = root.querySelector('.scg-hover-rail-doc');
var bar = root.querySelector('.scg-hover-rail-bar');
var thumb = root.querySelector('.scg-hover-rail-thumb');
var bubble = root.querySelector('.scg-hover-rail-bubble');
var where = root.querySelector('.scg-hover-rail-where');
var heads = [].slice.call(root.querySelectorAll('.scg-hover-rail-doc h4'));
var dragging = false, hideTimer = 0;
function ticks(){
  for (var i = 0; i < heads.length; i++) {
    var t = document.createElement('span');
    t.className = 'scg-hover-rail-tick';
    t.style.top = (heads[i].offsetTop / Math.max(1, doc.scrollHeight) * 100).toFixed(2) + '%';
    bar.insertBefore(t, thumb);
  }
}
function current(){
  var line = doc.scrollTop + 24, name = heads[0].getAttribute('data-name');
  for (var i = 0; i < heads.length; i++) if (heads[i].offsetTop <= line) name = heads[i].getAttribute('data-name');
  return name;
}
function flash(){
  root.classList.add('scg-hover-rail-show');
  clearTimeout(hideTimer);
  hideTimer = setTimeout(function(){ if (!dragging) root.classList.remove('scg-hover-rail-show'); }, 1100);
}
function sync(){
  var max = doc.scrollHeight - doc.clientHeight;
  var p = max > 0 ? Math.min(1, Math.max(0, doc.scrollTop / max)) : 0;
  var h = Math.max(26, doc.clientHeight / doc.scrollHeight * bar.clientHeight);
  thumb.style.height = h.toFixed(1) + 'px';
  thumb.style.transform = 'translateY(' + (p * (bar.clientHeight - h)).toFixed(1) + 'px)';
  thumb.setAttribute('aria-valuenow', String(Math.round(p * 100)));
  bubble.style.top = (p * (bar.clientHeight - h) + h / 2).toFixed(1) + 'px';
  var name = current();
  bubble.textContent = name;
  where.textContent = name;
}
function seek(clientY){
  var r = bar.getBoundingClientRect();
  var h = thumb.offsetHeight;
  var p = (clientY - r.top - h / 2) / Math.max(1, r.height - h);
  doc.scrollTop = Math.min(1, Math.max(0, p)) * (doc.scrollHeight - doc.clientHeight);
}
doc.addEventListener('scroll', function(){ sync(); flash(); }, { passive: true });
bar.addEventListener('pointerdown', function(e){
  dragging = true;
  root.classList.add('scg-hover-rail-drag', 'scg-hover-rail-show');
  try { bar.setPointerCapture(e.pointerId); } catch (err) {}
  seek(e.clientY);
});
bar.addEventListener('pointermove', function(e){ if (dragging) seek(e.clientY); });
function stop(e){
  dragging = false;
  root.classList.remove('scg-hover-rail-drag');
  try { bar.releasePointerCapture(e.pointerId); } catch (err) {}
  flash();
}
bar.addEventListener('pointerup', stop);
bar.addEventListener('pointercancel', stop);
bar.addEventListener('pointerenter', function(){ flash(); });
thumb.addEventListener('keydown', function(e){
  var step = 32, page = doc.clientHeight * 0.9, max = doc.scrollHeight - doc.clientHeight, k = e.key;
  var to = null;
  if (k === 'ArrowDown') to = doc.scrollTop + step;
  else if (k === 'ArrowUp') to = doc.scrollTop - step;
  else if (k === 'PageDown') to = doc.scrollTop + page;
  else if (k === 'PageUp') to = doc.scrollTop - page;
  else if (k === 'Home') to = 0;
  else if (k === 'End') to = max;
  if (to === null) return;
  e.preventDefault();
  doc.scrollTop = Math.min(max, Math.max(0, to));
  flash();
});
ticks();
sync();

