js:
var doc = root.querySelector('.scg-odometer-count-doc');
var reels = [].slice.call(root.querySelectorAll('.scg-odometer-count-reel'));
var hair = root.querySelector('.scg-odometer-count-hair');
var hairfill = root.querySelector('.scg-odometer-count-hairfill');
var words = root.querySelector('.scg-odometer-count-words');
var total = parseInt(words.getAttribute('data-total'), 10) || 600;
var last = -1;
for (var r = 0; r < reels.length; r++) {
  var out = '';
  for (var d = 0; d < 10; d++) out += '<span>' + d + '</span>';
  reels[r].innerHTML = out;
}
function roll(el, digit){
  el.style.transform = 'translateY(-' + (digit * 32) + 'px)';
}
function update(){
  var max = doc.scrollHeight - doc.clientHeight;
  var p = max > 0 ? Math.min(1, Math.max(0, doc.scrollTop / max)) : 1;
  var v = Math.round(p * 100);
  hairfill.style.width = (p * 100).toFixed(2) + '%';
  if (v === last) return;
  last = v;
  hair.setAttribute('aria-valuenow', String(v));
  root.classList.toggle('scg-odometer-count-full', v >= 100);
  roll(reels[0], v >= 100 ? 1 : 0);
  roll(reels[1], Math.floor(v / 10) % 10);
  roll(reels[2], v % 10);
  var read = Math.round(p * total);
  words.textContent = read + ' / ' + total + ' words';
}
doc.addEventListener('scroll', update, { passive: true });
update();

