js:
var view = root.querySelector('.scg-page-pips-view');
var pages = [].slice.call(root.querySelectorAll('.scg-page-pips-page'));
var pips = root.querySelector('.scg-page-pips-pips');
var count = root.querySelector('.scg-page-pips-count');
var arrows = root.querySelectorAll('.scg-page-pips-arrow');
var dots = [], idx = -1;
for (var i = 0; i < pages.length; i++) {
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'scg-page-pips-pip';
  b.setAttribute('aria-label', 'Go to page ' + (i + 1));
  b.setAttribute('data-i', String(i));
  b.addEventListener('click', function(e){
    go(parseInt(e.currentTarget.getAttribute('data-i'), 10));
  });
  pips.appendChild(b);
  dots.push(b);
}
function go(n){
  view.scrollTop = Math.min(pages.length - 1, Math.max(0, n)) * view.clientHeight;
}
function update(){
  var n = Math.round(view.scrollTop / Math.max(1, view.clientHeight));
  n = Math.min(pages.length - 1, Math.max(0, n));
  if (n === idx) return;
  idx = n;
  count.textContent = 'Page ' + (n + 1) + ' of ' + pages.length;
  for (var k = 0; k < dots.length; k++) dots[k].setAttribute('aria-current', k === n ? 'true' : 'false');
  arrows[0].disabled = n === 0;
  arrows[1].disabled = n === pages.length - 1;
}
for (var a = 0; a < arrows.length; a++) {
  arrows[a].addEventListener('click', function(e){
    go(idx + parseInt(e.currentTarget.getAttribute('data-dir'), 10));
  });
}
view.addEventListener('scroll', update, { passive: true });
update();

