js:
var list = root.querySelector('.scg-issue-gutter-list');
var track = root.querySelector('.scg-issue-gutter-track');
var lens = root.querySelector('.scg-issue-gutter-lens');
var pos = root.querySelector('.scg-issue-gutter-pos');
var next = root.querySelector('.scg-issue-gutter-next');
var rows = [].slice.call(root.querySelectorAll('.scg-issue-gutter-row'));
var errs = [], i;
for (i = 0; i < rows.length; i++) if (rows[i].getAttribute('data-sev') === 'err') errs.push(rows[i]);
var cursor = -1;
function build(){
  var h = list.scrollHeight || 1;
  for (var k = 0; k < rows.length; k++) {
    var m = document.createElement('span');
    m.className = 'scg-issue-gutter-mk scg-issue-gutter-mk-' + rows[k].getAttribute('data-sev');
    m.style.top = ((rows[k].offsetTop + 6) / h * 100).toFixed(2) + '%';
    track.insertBefore(m, lens);
  }
}
function sync(){
  var h = list.scrollHeight || 1;
  var scale = track.clientHeight / h;
  lens.style.height = Math.max(14, list.clientHeight * scale).toFixed(1) + 'px';
  lens.style.transform = 'translateY(' + (list.scrollTop * scale).toFixed(1) + 'px)';
  var line = list.scrollTop + 10, n = 1;
  for (var k = 0; k < rows.length; k++) if (rows[k].offsetTop <= line) n = k + 1;
  pos.textContent = n + ' of ' + rows.length;
}
function focusRow(el){
  list.scrollTop = el.offsetTop - 6;
  for (var k = 0; k < rows.length; k++) rows[k].classList.toggle('scg-issue-gutter-hit', rows[k] === el);
}
next.addEventListener('click', function(){
  cursor = (cursor + 1) % errs.length;
  focusRow(errs[cursor]);
});
track.addEventListener('click', function(e){
  var r = track.getBoundingClientRect();
  var p = (e.clientY - r.top) / Math.max(1, r.height);
  list.scrollTop = p * list.scrollHeight - list.clientHeight / 2;
});
list.addEventListener('scroll', sync, { passive: true });
build();
sync();

