.scg-story-segments{--scg-ss-a:#c084fc;--scg-ss-b:#f472b6;box-sizing:border-box;width:100%;max-width:352px;padding:11px 11px 12px;border-radius:16px;background:linear-gradient(180deg,#150f1d,#08070c);border:1px solid rgba(192,132,252,.18);color:#f2ecfa;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;}
