.scg-story-segments-seg:focus-visible{outline:2px solid var(--scg-ss-a);outline-offset:1px;border-radius:4px;}
.scg-story-segments-in{display:block;height:3px;margin-top:4px;border-radius:99px;background:rgba(242,236,250,.16);overflow:hidden;}
