js:
var scroll = root.querySelector('.scg-story-segments-scroll');
var bars = root.querySelector('.scg-story-segments-bars');
var idxEl = root.querySelector('.scg-story-segments-idx');
var nameEl = root.querySelector('.scg-story-segments-name');
var metaEl = root.querySelector('.scg-story-segments-meta');
var titleEl = root.querySelector('.scg-story-segments-title');
var secs = [].slice.call(root.querySelectorAll('.scg-story-segments-sec'));
var fills = [], active = -1, i;
for (i = 0; i < secs.length; i++) {
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'scg-story-segments-seg';
  b.setAttribute('data-i', String(i));
  b.setAttribute('aria-label', 'Chapter ' + (i + 1) + ': ' + secs[i].getAttribute('data-name'));
  b.innerHTML = '<span class="scg-story-segments-in"><span class="scg-story-segments-fill"></span></span>';
  b.addEventListener('click', function(e){
    var n = parseInt(e.currentTarget.getAttribute('data-i'), 10);
    scroll.scrollTop = secs[n].offsetTop - 2;
  });
  bars.appendChild(b);
  fills.push(b.querySelector('.scg-story-segments-fill'));
}
function update(){
  var line = scroll.scrollTop + scroll.clientHeight * 0.35;
  var atEnd = scroll.scrollTop + scroll.clientHeight >= scroll.scrollHeight - 2;
  var live = 0;
  for (var k = 0; k < secs.length; k++) {
    var top = secs[k].offsetTop, h = Math.max(1, secs[k].offsetHeight);
    var f = Math.min(1, Math.max(0, (line - top) / h));
    if (atEnd) f = 1;
    fills[k].style.width = (f * 100).toFixed(1) + '%';
    if (f > 0) live = k;
  }
  if (atEnd) live = secs.length - 1;
  if (live !== active) {
    active = live;
    idxEl.textContent = (live < 9 ? '0' : '') + (live + 1);
    nameEl.textContent = secs[live].getAttribute('data-name');
    metaEl.textContent = secs[live].getAttribute('data-meta');
    titleEl.classList.remove('scg-story-segments-swap');
    void titleEl.offsetWidth;
    titleEl.classList.add('scg-story-segments-swap');
  }
}
scroll.addEventListener('scroll', update, { passive: true });
update();
